import math
def solve(name, x, grad):
    if name=="relu": y=[max(0,v) for v in x]; dx=[g*(v>0) for v,g in zip(x,grad)]
    elif name=="sigmoid":
        y=[1/(1+math.exp(-v)) for v in x]; dx=[g*a*(1-a) for g,a in zip(grad,y)]
    elif name=="tanh":
        y=[math.tanh(v) for v in x]; dx=[g*(1-a*a) for g,a in zip(grad,y)]
    elif name=="gelu":
        c=math.sqrt(2/math.pi); y=[]; dx=[]
        for v,g in zip(x,grad):
            t=math.tanh(c*(v+0.044715*v**3)); a=0.5*v*(1+t)
            d=0.5*(1+t)+0.5*v*(1-t*t)*c*(1+3*0.044715*v*v)
            y.append(a); dx.append(g*d)
    else: raise ValueError("unknown activation")
    return y,dx

